function setupCellEditing() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) {
        console.error("Error: No se encontró la tabla de cálculo.");
        return;
    }

    /**
     * Recalcula todas las celdas que dependen del ID de celda proporcionado.
     * @param {string} changedCellId - El ID de la celda que cambió (ej: 'B1').
     * @param {HTMLElement} targetElement - El elemento TD que disparó el evento.
     */
    function recalculateDependencies(changedCellId, targetElement) {
        // 1. Obtener todas las celdas de datos en la hoja
        const dataCells = spreadsheet.querySelectorAll('td[data-cell]');

        for (const cell of dataCells) {
            const cellId = cell.getAttribute('data-cell');

            // No recalcular el objetivo si es un valor manual, solo si tiene fórmula y no es él mismo
            if (cellId === changedCellId && !cell.hasAttribute('data-formula')) continue;

            const formula = cell.innerText.trim();
            if (!formula || !formula.startsWith('=')) {
                continue; // No es una celda con fórmula, ignorar
            }

            // 2. Verificar si la fórmula contiene el ID de la celda que cambió
            // Usamos una expresión regular para buscar referencias a celdas (ej: B1)
            const dependencyRegex = new RegExp(changedCellId, 'g');
            if (dependencyRegex.test(formula)) {
                // 3. Si depende del cambio, recalcular la celda
                calculateCell(cell);
            }
        }
    }

    // Usamos event delegation para escuchar en toda la tabla, 
    // pero solo actuar si el elemento objetivo es una celda de datos editable.
    spreadsheet.addEventListener('input', function(event) {
        const target = event.target;

        // Verificamos que el elemento sea un TD y tenga el atributo data-cell
        if (target.tagName === 'TD' && target.hasAttribute('data-cell')) {
            const changedCellId = target.getAttribute('data-cell');
            console.log(`Celda ${changedCellId} actualizada con: "${target.innerText}"`);

            // 1. Calcular inmediatamente al escribir (actualiza el valor del objetivo)
            calculateCell(target); 

            // 2. Recalcular todas las celdas que dependan de este cambio
            recalculateDependencies(changedCellId, target);
        }
    });

    // También es bueno manejar el blur (cuando sale de la celda) para simular un "guardado" o validación final.
    spreadsheet.addEventListener('blur', function(event) {
        const target = event.target;
        if (target.tagName === 'TD' && target.hasAttribute('data-cell')) {
            const changedCellId = target.getAttribute('data-cell');
            console.log(`Celda ${changedCellId} perdió el foco.`);

            // 1. Calcular al perder el foco (actualiza el valor del objetivo)
            calculateCell(target); 

            // 2. Recalcular todas las celdas que dependan de este cambio
            recalculateDependencies(changedCellId, target);
        }
    });
}
