function setupColumnSelection() {
    const headerRow = document.querySelector('#spreadsheet thead tr');
    if (!headerRow) return;

    // Select all column letter headers (A, B, C, ...)
    const columnHeaders = Array.from(headerRow.querySelectorAll('th:not(:first-child)'));

    columnHeaders.forEach((header, index) => {
        // Add click listener to each header
        header.addEventListener('click', function() {
            const colLetter = this.textContent;
            const colIndex = index + 1; // A=1, B=2, ... (since we skip the corner cell)

            // Update selection state and UI controls
            selectColumn(colLetter, colIndex);
        });
    });

    // Attach event listener to the delete button
    document.getElementById('deleteColumnButton').addEventListener('click', () => {
        const selectedCol = window.selectedColumn;
        if (selectedCol) {
            deleteColumn(selectedCol.letter, selectedCol.index);
        } else {
            alert("Por favor, selecciona una columna primero.");
        }
    });
}
```

### FUNCION: selectColumn
```js
function selectColumn(letter, index) {
    // Deseleccionar cualquier columna previamente seleccionada
    document.querySelectorAll('.column-header').forEach(th => {
        th.classList.remove('selected');
    });

    // Marcar la columna actual como seleccionada
    const selectedHeader = document.querySelector(`th:contains("${letter}")`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    window.selectedColumn = { letter: letter, index: index };
    document.getElementById('columnDisplay').textContent = `Columna ${letter}`;
    document.getElementById('deleteColumnButton').disabled = false;
    document.getElementById('clearColumnButton').disabled = false;
    document.getElementById('colorColumnButton').disabled = false;

    // Opcional: Enfocar la primera celda de esa columna para mejor UX
    const firstCell = document.querySelector(`[data-cell="${letter}1"]`);
    if (firstCell) {
        firstCell.focus();
    }
}
```

### FUNCION: deleteColumn
```js
function deleteColumn(letter, index) {
    if (!confirm(`¿Estás seguro de que deseas eliminar la columna ${letter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Eliminar el contenido de todas las celdas en esa columna
    const cells = document.querySelectorAll(`[data-cell^="${letter}"]`);
    cells.forEach(cell => {
        cell.textContent = '';
        cell.innerHTML = ''; // Limpiar también cualquier HTML interno
        // Restaurar color por defecto si es necesario, aunque el DOM lo maneja bien
        cell.style.backgroundColor = ''; 
    });

    // 2. Eliminar las celdas de la tabla (TDs)
    const rows = document.querySelectorAll('#spreadsheet tbody tr');
    rows.forEach(row => {
        const cellsInRow = row.querySelectorAll(`[data-cell^="${letter}"]`);
        cellsInRow.forEach(cell => cell.remove());
    });

    // 3. Eliminar el encabezado de la columna (TH)
    const headerToRemove = document.querySelector(`#spreadsheet thead tr th:contains("${letter}")`);
    if (headerToRemove) {
        headerToRemove.remove();
    }

    // Resetear estado
    window.selectedColumn = null;
    document.getElementById('columnDisplay').textContent = 'Columna';
    document.getElementById('deleteColumnButton').disabled = true;
    document.getElementById('clearColumnButton').disabled = true;
    document.getElementById('colorColumnButton').disabled = true;

    alert(`La columna ${letter} ha sido eliminada.`);
}
