/**
 * Applies a background color to every cell in a specified column.
 * @param {string} columnLetter - The letter of the column (e.g., 'A').
 * @param {string} color - The hex color string (e.g., '#ff0000').
 */
function handleApplyBackground(columnLetter, color) {
    // Regex para encontrar todas las celdas de la columna dada: [data-cell="A1"], [data-cell="A2"], etc.
    const selector = `[data-cell^="${columnLetter}"]`;
    const cells = document.querySelectorAll(selector);

    if (cells.length === 0) {
        console.warn(`No se encontraron celdas en la columna ${columnLetter}.`);
        return;
    }

    // Aplicar el fondo a cada celda encontrada
    cells.forEach(cell => {
        // Usamos style.backgroundColor para asegurar que el estilo inline anule cualquier CSS preexistente.
        cell.style.backgroundColor = color;
    });
}
