/**
 * Configura los listeners para las etiquetas de fila (row-1 a row-20) 
 * para manejar la selección y acciones de la fila completa.
 */
function setupRowSelectionListeners() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // Seleccionamos todos los contenedores de etiquetas de fila (row-1, row-2, etc.)
    const rowLabels = document.querySelectorAll('.row-label');

    rowLabels.forEach(label => {
        label.addEventListener('click', function() {
            const rowIndex = this.id.replace('row-', ''); // Obtiene el número de la fila (ej: '3')
            if (!rowIndex) return;

            // 1. Deseleccionar todas las filas primero
            document.querySelectorAll('.row-label').forEach(l => l.classList.remove('selected'));
            this.classList.add('selected');

            // 2. Aplicar la selección visual a la fila en el spreadsheet (opcional, pero bueno para UX)
            const rowElement = document.getElementById(`row-${rowIndex}`);
            if (rowElement) {
                rowElement.style.backgroundColor = '#eee'; // Color de fondo temporal para indicar selección
            }

            // 3. Mostrar la funcionalidad de acciones (ej: un panel lateral o botones, si existieran).
            console.log(`Fila ${rowIndex} seleccionada.`);
        });
    });
}

/**
 * Aplica el color de fondo a todas las celdas (<td>) de una fila específica.
 * @param {string} rowIndex - El índice de la fila (ej: '3').
 * @param {string} color - El código de color hexadecimal o RGB.
 */
function applyRowBackground(rowIndex, color) {
    const rowElement = document.getElementById(`row-${rowIndex}`);
    if (!rowElement) return;

    // FIX: Iterar sobre todos los <td> dentro del contenedor de la fila y aplicar el estilo directamente a ellos.
    const cells = rowElement.querySelectorAll('td[data-cell]');
    cells.forEach(cell => {
        cell.style.backgroundColor = color;
    });
}

/**
 * Limpia el contenido de todas las celdas (<td>) de una fila específica.
 * @param {string} rowIndex - El índice de la fila (ej: '3').
 */
function clearRowContent(rowIndex) {
    const rowElement = document.getElementById(`row-${rowIndex}`);
    if (!rowElement) return;

    // Limpiar contenido y resetear estilos básicos
    const cells = rowElement.querySelectorAll('td[data-cell]');
    cells.forEach(cell => {
        cell.innerText = '';
        cell.style.backgroundColor = ''; // Resetear color de fondo
        cell.dataset.isCalculated = 'false';
    });
}

/**
 * Elimina completamente la fila (contenedor y contenido) del DOM.
 * @param {string} rowIndex - El índice de la fila (ej: '3').
 */
function deleteRow(rowIndex) {
    const rowElement = document.getElementById(`row-${rowIndex}`);
    if (rowElement) {
        // Eliminar el contenedor completo de la fila del DOM
        rowElement.remove();
        console.log(`Fila ${rowIndex} eliminada.`);
    }
}

/**
 * Inicializa los listeners para las acciones de la fila completa, 
 * incluyendo coloración y limpieza.
 */
function setupRowActionListeners() {
    // Asumimos que hay un botón o mecanismo global para aplicar el fondo/limpiar/borrar.
    const applyColorButton = document.getElementById('applyColorButton');
    const clearContentButton = document.getElementById('clearContentButton');
    const deleteRowButton = document.getElementById('deleteRowButton');

    // Listener para Aplicar Fondo
    if (applyColorButton) {
        applyColorButton.addEventListener('click', function() {
            const selectedLabel = document.querySelector('.row-label.selected');
            if (!selectedLabel) {
                alert("Por favor, selecciona una fila primero.");
                return;
            }
            const rowIndex = selectedLabel.id.replace('row-', '');
            const colorPicker = document.getElementById('cellColorPicker');
            const color = colorPicker.value;

            if (color) {
                applyRowBackground(rowIndex, color);
            } else {
                alert("Por favor, selecciona un color.");
            }
        });
    }

    // Listener para Limpiar Contenido
    if (clearContentButton) {
        clearContentButton.addEventListener('click', function() {
            const selectedLabel = document.querySelector('.row-label.selected');
            if (!selectedLabel) {
                alert("Por favor, selecciona una fila primero.");
                return;
            }
            const rowIndex = selectedLabel.id.replace('row-', '');
            if (confirm(`¿Estás seguro de que quieres borrar el contenido de la Fila ${rowIndex}?`)) {
                clearRowContent(rowIndex);
            }
        });
    }

    // Listener para Borrar Fila
    if (deleteRowButton) {
        deleteRowButton.addEventListener('click', function() {
            const selectedLabel = document.querySelector('.row-label.selected');
            if (!selectedLabel) {
                alert("Por favor, selecciona una fila primero.");
                return;
            }
            const rowIndex = selectedLabel.id.replace('row-', '');
            if (confirm(`¿Estás seguro de que quieres eliminar permanentemente la Fila ${rowIndex}?`)) {
                deleteRow(rowIndex);
            }
        });
    }
}
