/**
 * Clears all content from a specified row (1-based index).
 * @param {number} rowIndex - The 1-based index of the row to clear.
 */
function clearRowContent(rowIndex) {
    if (!rowIndex || isNaN(parseInt(rowIndex))) return;

    const row = parseInt(rowIndex); // Aseguramos que sea un número entero
    // Iterar sobre las columnas A a Z (26 columnas)
    for (let colIndex = 0; colIndex < 26; colIndex++) {
        // getCellIdFromCoordinates usa índices base 0 para la fila, por eso restamos 1.
        const cellId = getCellIdFromCoordinates(row - 1, colIndex); 
        const element = document.querySelector(`[data-cell="${cellId}"]`);
        if (element) {
            // Limpiar contenido y resetear estado de cálculo
            element.innerText = '';
            delete element.dataset; // Eliminar atributos de datos como data-is-calculated
            element.removeAttribute('data-is-calculated'); 
        }
    }
