/**
 * Oculta una columna específica (por su letra, ej: 'A').
 * @param {string} colLetter - La letra de la columna.
 */
function hideColumn(colLetter) {
    const columnElement = document.querySelector(`[data-column="${colLetter}"]`);
    if (!columnElement) {
        console.warn(`Columna ${colLetter} no encontrada.`);
        return;
    }

    // Ocultar el encabezado de la columna
    columnElement.style.display = 'none'; 

    // Iterar sobre todas las filas y ocultar los TDs correspondientes a esta columna
    const rows = document.querySelectorAll('.spreadsheet-row'); // Asumiendo que cada fila tiene esta clase
    rows.forEach(row => {
        const cell = row.querySelector(`[data-column="${colLetter}"]`);
        if (cell) {
            cell.style.display = 'none';
        }
    });

    console.log(`Columna ${colLetter} oculta.`);
}
