/**
 * R8 Helper: Configura los listeners para las cabeceras de columna (A, B, C...).
 * Permite ocultar y mostrar columnas haciendo clic en su letra.
 */
function setupHeaderListeners() {
    // Asumimos que hay un contenedor visible para las letras de las columnas. 
    // Si no se proporciona el selector exacto, usamos 'thead' o similar como punto de partida.
    const headerContainer = document.querySelector('.spreadsheet-header'); 

    if (!headerContainer) {
        console.warn("Advertencia: No se encontró el contenedor de cabeceras de columna.");
        return;
    }

    // Usamos event delegation para capturar clics en cualquier letra de columna dentro del contenedor.
    headerContainer.addEventListener('click', function(event) {
        const target = event.target;
        // Verificamos si el elemento clickeado es un encabezado de columna (ej: la letra 'A')
        if (target.classList.contains('column-label')) { 
            const colLetter = target.innerText.trim().toUpperCase();
            toggleColumnVisibility(colLetter);
        }
    });
}

/**
 * R8 Helper: Alterna la visibilidad de una columna completa.
 */
function toggleColumnVisibility(colLetter) {
    // 1. Obtener el elemento del encabezado y alternar su estado (si es necesario).
    const headerElement = document.querySelector(`.column-label[data-letter="${colLetter}"]`);

    if (!headerElement) {
        console.error(`No se encontró la cabecera de columna para ${colLetter}.`);
        return;
    }

    // 2. Determinar si está visible o no (usando un atributo data-hidden).
    const isHidden = headerElement.getAttribute('data-hidden') === 'true';

    if (isHidden) {
        // Mostrar la columna: Quitar el atributo de oculto y restaurar estilos.
        headerElement.removeAttribute('data-hidden');
        headerElement.style.display = ''; 

        // Ocultar todas las celdas que pertenecen a esta columna en el cuerpo principal.
        const selector = `[data-column="${colLetter}"]`; 
        document.querySelectorAll(selector).forEach(el => {
            el.style.display = ''; // Mostrar
        });
    } else {
        // Ocultar la columna: Añadir atributo de oculto y aplicar estilos 'none'.
        headerElement.setAttribute('data-hidden', 'true');
        headerElement.style.display = 'none';

        // Ocultar todas las celdas que pertenecen a esta columna en el cuerpo principal.
        const selector = `[data-column="${colLetter}"]`; 
        document.querySelectorAll(selector).forEach(el => {
            el.style.display = 'none'; // Ocultar
        });
    }
}
