function showContextMenu(e) {
    // Prevenir el menú contextual nativo del navegador
    e.preventDefault();

    const rowLabelElement = e.currentTarget;
    if (!rowLabelElement) return;

    const rowNumber = rowLabelElement.innerText.trim();
    const contextMenu = document.getElementById('context-menu');
    const menuItems = contextMenu.querySelectorAll('.context-item');

    // 1. Configurar el contenido del menú
    if (rowNumber) {
        document.querySelector('#context-menu .row-info').innerText = `Fila ${rowNumber}`;

        // Habilitar/Deshabilitar opciones basadas en si la fila está oculta o visible
        const isRowHidden = rowLabelElement.parentElement.style.display === 'none';

        document.getElementById('hide-row-option').style.display = isRowHidden ? 'none' : 'block';
        document.getElementById('show-row-option').style.display = isRowHidden ? 'none' : 'block';
    } else {
        // Si no hay fila identificada, limpiar el menú
        contextMenu.innerHTML = '';
    }

    // 2. Posicionar y mostrar el menú
    const menuRect = contextMenu.getBoundingClientRect();

    // Ajustar la posición para que aparezca cerca del cursor o en un lugar visible
    let topPos = e.clientY - menuRect.height / 2;
    let leftPos = e.clientX + 10;

    if (topPos < 0) {
        topPos = e.clientY; // Si está muy arriba, empezar desde el cursor Y
    }

    contextMenu.style.top = `${topPos}px`;
    contextMenu.style.left = `${leftPos}px`;
    contextMenu.style.display = 'block';
}
