### FUNCION: setupRowColumnHiding
```js
/**
 * R8. Configura la funcionalidad para ocultar filas y columnas haciendo clic en sus etiquetas.
 */
function setupRowColumnHiding() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) return;

    // 1. Manejo de Ocultar Fila (Click en el número de fila, ej: 'row-label' con data-row)
    document.querySelectorAll('.row-label').forEach(label => {
        label.addEventListener('click', function() {
            const rowNum = this.getAttribute('data-row');
            if (!rowNum) return;

            // Alternar visibilidad de la fila completa y su etiqueta
            const rowElement = document.getElementById(`row-${rowNum}`);
            if (rowElement) {
                const isHidden = rowElement.style.display === 'none';
                if (isHidden) {
                    // Mostrar: Quitar el estilo display: none de la fila y la etiqueta
                    rowElement.style.display = ''; 
                    this.style.display = '';
                } else {
                    // Ocultar: Aplicar display: none a la fila y la etiqueta
                    rowElement.style.display = 'none';
                    this.style.display = 'none';
                }
            }
        });
    });

    // 2. Manejo de Ocultar Columna (Click en el encabezado de columna, ej: A, B, C...)
    const columnHeaders = document.querySelectorAll('.column-header');
    columnHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const colLetter = this.getAttribute('data-col');
            if (!colLetter) return;

            // Ocultar la columna en todas las filas de datos (A1:J20)
            document.querySelectorAll(`[data-cell^="${colLetter}"]`).forEach(cell => {
                const isHidden = cell.style.display === 'none';
                if (!isHidden) {
                    // Ocultar la columna en todas las celdas de datos
                    cell.style.display = 'none';
                } else {
                    // Mostrar la columna
                    cell.style.display = '';
                }
            });

            // Alternar visibilidad del encabezado de columna y su etiqueta
            const isHidden = this.style.display === 'none';
            if (isHidden) {
                this.style.display = '';
            } else {
                this.style.display = 'none';
            }
        });
    });
}
