/**
 * Configura el manejador de eventos para permitir la eliminación de columnas 
 * al presionar 'Delete' mientras se está en un encabezado de columna.
 */
function setupColumnDeletionHandler() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) {
        console.error("Error: No se encontró la tabla de cálculo para manejar la eliminación de columnas.");
        return;
    }

    // Usamos event delegation en el contenedor principal para capturar eventos de teclado.
    spreadsheet.addEventListener('keydown', function(event) {
        const target = event.target;

        // Solo procesar si se presiona Delete o Backspace y estamos sobre un elemento que representa una columna (o la tabla misma).
        if ((event.key === 'Delete' || event.key === 'Backspace') && 
            (target.tagName === 'TD' || target.closest('#spreadsheet'))) {

            // Intentamos determinar el índice de la columna activa o seleccionada.
            let colLetter = '';
            let columnIndex = -1;

            // Si estamos en una celda, usamos su data-cell para obtener la letra.
            if (target.hasAttribute('data-cell')) {
                const cellId = target.getAttribute('data-cell');
                colLetter = cellId.match(/[A-Z]+/)[0];
                columnIndex = getColumnIndexFromLetter(colLetter);
            } else if (target.closest('#spreadsheet') && event.key === 'Delete') {
                 // Si el foco está en la tabla pero no en una celda, asumimos que se debe usar el contexto de la columna activa/visible. 
                 // Dado que es difícil determinar esto sin un enfoque más complejo, nos limitaremos a lo detectado por data-cell o si el target es visiblemente un encabezado (lo cual no está modelado).
            }

            if (colLetter && columnIndex !== -1) {
                event.preventDefault(); // Prevenir la acción por defecto del navegador (ej: borrar texto)
                deleteColumn(columnIndex);
            } else if (!target.hasAttribute('data-cell') && target.closest('#spreadsheet')) {
                 // Si no podemos determinar la columna, ignoramos el evento para evitar errores.
            }
        }
    });
}

/**
 * Helper function to convert column letter (e.g., 'B') to zero-based index (0 for A, 1 for B).
 */
function getColumnIndexFromLetter(letter) {
    let index = 0;
    for (let i = 0; i < letter.length; i++) {
        index = index * 26 + (letter.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    return index - 1; // Convertir a índice base 0
}

/**
 * Elimina una columna completa del DOM y de LocalStorage, ajustando los índices si fuera necesario.
 * @param {number} columnIndex - El índice (base 0) de la columna a eliminar.
 */
function deleteColumn(columnIndex) {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    let columnLetter = '';
    // Obtener la letra correspondiente al índice antes de borrar
    for (let i = 0; i < columnIndex; i++) {
        columnLetter += String.fromCharCode('A'.charCodeAt(0) + i);
    }
    columnLetter += String.fromCharCode('A'.charCodeAt(0) + columnIndex);

    console.log(`Intentando eliminar la columna: ${columnLetter}`);

    // 1. Eliminar elementos del DOM
    const rows = spreadsheet.querySelectorAll('.row-data'); // Asumiendo que las filas de datos tienen esta clase o estructura similar
    let cellsDeletedCount = 0;

    rows.forEach(row => {
        const cellsInRow = row.querySelectorAll('td[data-cell]');
        if (cellsInRow.length > columnIndex) {
            // Eliminar la celda en el índice de columna dado
            const cellToDelete = cellsInRow[columnIndex];
            if (cellToDelete) {
                cellToDelete.remove();
                cellsDeletedCount++;
            }
        }
    });

    // 2. Limpiar LocalStorage para todas las celdas que estaban en esa columna
    let keysToDelete = [];
    document.querySelectorAll('[data-cell]').forEach(cell => {
        const cellId = cell.getAttribute('data-cell');
        if (cellId.match(/^[A-Z]+[0-9]+$/)) { // Validación simple de formato A1, B2...
            const colLetterMatch = cellId.match(/^([A-Z]+)/);
            if (colLetterMatch) {
                const currentColLetter = colLetterMatch[1];
                const targetColumnLetter = columnLetter.match(/^([A-Z]+)/)[0];

                // Si la letra de la columna coincide, guardamos la clave para borrarla
                if (currentColLetter === targetColumnLetter) {
                    keysToDelete.push(`spreadsheet_${cellId}`);
                }
            }
        }
    });

    keysToDelete.forEach(key => {
        localStorage.removeItem(key);
    });

    console.log(`Columna ${columnLetter} eliminada exitosamente.`);
    // Nota: En una aplicación real, se debería re-renderizar la tabla para ajustar todos los índices y estructuras de datos. 
    // Aquí solo removemos el contenido visible y los datos guardados.
}
