function deleteColumn(colLetter) {
    if (!colLetter || !/[A-Z]/.test(colLetter)) return;

    const spreadsheet = document.getElementById('spreadsheet');
    const headerRow = spreadsheet.querySelector('thead tr');
    let columnIndex = -1;

    // 1. Find the index of the column letter (A=0, B=1, ...)
    const headers = Array.from(headerRow.querySelectorAll('th:not(:first-child)')); // Exclude corner cell
    for (let i = 0; i < headers.length; i++) {
        if (headers[i].textContent.trim() === colLetter) {
            columnIndex = i;
            break;
        }
    }

    if (columnIndex === -1) {
        console.error(`Column ${colLetter} not found.`);
        return;
    }

    // 2. Remove the header cell
    headers[columnIndex].remove();

    // 3. Iterate through all body rows and remove the corresponding cell
    const rows = spreadsheet.querySelectorAll('tbody tr');
    rows.forEach(row => {
        // Get all data cells in the row (excluding the first label cell)
        const cells = Array.from(row.querySelectorAll('td'));
        if (cells[columnIndex]) {
            cells[columnIndex].remove();
        }
    });

    console.log(`Column ${colLetter} deleted successfully.`);
    // Note: A full implementation would require re-indexing data attributes and recalculating formulas, 
    // but for basic deletion visibility, this is sufficient.
