function deleteColumn(colLetter) {
    if (!colLetter || !/[A-Z]/.test(colLetter)) return;

    const spreadsheet = document.getElementById('spreadsheet');
    // Select only the header cells in thead that represent columns A-J (excluding the corner cell)
    const headerRow = spreadsheet.querySelector('thead tr'); 
    let columnIndex = -1;

    // 1. Find the index of the column letter (A=0, B=1, ...) among the actual headers
    const headers = Array.from(headerRow.querySelectorAll('th:not(:first-child)')); 
    for (let i = 0; i < headers.length; i++) {
