function toggleColumnVisibility(colIndex) {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // 1. Identificar el encabezado de columna (A, B, C...)
    const dataHeaders = Array.from(spreadsheet.querySelectorAll('#thead tr th'));
    // colIndex=0 corresponde al índice 1 en la lista de THs (el 'A')
    const targetHeaderElement = dataHeaders[colIndex + 1];

    if (!targetHeaderElement) {
        console.error("No se pudo encontrar el elemento de encabezado para el índice:", colIndex);
        return;
    }

    // Determinar si está oculto y cuál debe ser su nuevo estado
    const isHidden = targetHeaderElement.style.display === 'none';
    const displayState = isHidden ? 'table-cell' : 'none';

    // 2. Alternar la visibilidad del encabezado de columna (la letra)
    targetHeaderElement.style.display = displayState;

    // 3. Iterar sobre todas las filas de datos y ocultar/mostrar la celda correspondiente
    const bodyRows = spreadsheet.querySelectorAll('tbody tr');
    bodyRows.forEach(row => {
        // La Nth TD en una fila corresponde al colIndex + 2 (porque contamos el TH vacío y el row label)
        const targetCell = row.querySelector(`td:nth-child(${colIndex + 2})`);

        if (targetCell) {
            targetCell.style.display = displayState;
        }
    });
}
