```javascript
/**
 * Setup Cell Editing and Event Listeners
 */
function setupCellEditing() {
    const cells = document.querySelectorAll('[contenteditable="true"]');
    cells.forEach(cell => {
        // Add event listener for input changes (typing)
        cell.addEventListener('input', function() {
            handleInput(this);
        });

        // Add event listener for focus/blur to ensure calculations run when editing stops
        cell.addEventListener('focus', function() {
            // Optional: Highlight cell on focus
        });
        cell.addEventListener('blur', function() {
            handleInput(this); // Recalculate when leaving the cell
        });
    });
}

/**
 * Handles input changes in a cell, triggering recalculation if necessary.
 * @param {HTMLElement} cellElement - The cell element that was edited.
 */
function handleInput(cellElement) {
    const content = cellElement.textContent.trim();
    // Check if the content looks like a formula (starts with =)
    if (content.startsWith('=')) {
        calculateCell(cellElement);
    } else {
        // If it's plain text, just update local storage and recalculate dependents
        updateLocalStorage(cellElement, content);
        calculateAllFormulas();
    }
}

/**
 * Gets the coordinates (A1 format) of a given cell element.
 * @param {HTMLElement} cellId - The cell element.
 * @returns {string|null} The coordinate string (e.g., "A3").
 */
function getCoordinates(cellId) {
    const dataCell = cellId.getAttribute('data-cell');
    if (dataCell) {
        return dataCell;
    }
    return null;
}

/**
 * Gets the row number of a given cell element.
 * @param {HTMLElement} cellElement - The cell element.
 * @returns {number|null} The row number.
 */
function getRowNumber(cellElement) {
    const dataCell = cellElement.getAttribute('data-cell');
    if (dataCell && !isNaN(parseInt(dataCell.slice(-1)))) {
        return parseInt(dataCell.slice(-1));
    }
    return null;
}

/**
 * Gets the column letter of a given cell element.
 * @param {HTMLElement} cellElement - The cell element.
 * @returns {string|null} The column letter (e.g., "A").
 */
function getColumnLetter(cellElement) {
    const dataCell = cellElement.getAttribute('data-cell');
    if (dataCell && dataCell.length > 0) {
        return dataCell.charAt(0);
    }
    return null;
}

/**
 * Gets the coordinates (A1 format) from row and column index.
 * @param {number} row - The row number (1-indexed).
 * @param {string} colLetter - The column letter (e.g., "A").
 * @returns {string} The coordinate string (e.g., "A3").
 */
function getCellIdFromCoordinates(row, colLetter) {
    return `${colLetter}${row}`;
}

/**
 * Calculates the value of a cell based on its content (formula or number).
 * @param {HTMLElement} cellElement - The cell element to calculate.
 * @returns {number|string} The calculated numeric value or formula string if invalid.
 */
function calculateCell(cellElement) {
    let content = cellElement.textContent.trim();

    if (!content || !content.startsWith('=')) {
        // Not a formula, just update storage and return original content
        updateLocalStorage(cellElement, content);
        return content;
    }

    try {
        // Simple evaluation for basic arithmetic formulas (e.g., =A1+B1)
        // We must replace cell references like A1 with their actual values before eval()
        let formulaString = content.replace(/([A-Z]+[0-9]+)/g, (match) => {
            const targetCell = document.querySelector(`[data-cell="${match}"]`);
            if (targetCell && targetCell.textContent.trim().startsWith('=')) {
                // If the referenced cell is a formula, use its calculated value for evaluation context
                return parseFloat(targetCell.getAttribute('data-value') || 0);
            } else if (targetCell) {
                // Otherwise, use its current text content (which should be the value)
                const val = targetCell.textContent.trim();
                if (!isNaN(parseFloat(val))) return parseFloat(val);
                return val; // Return string if not numeric
            }
            return '0'; // Default to 0 if cell is missing
        });

        // Use Function constructor for safe evaluation context (safer than raw eval)
        const result = new Function('return ' + formulaString)();

        if (isNaN(result)) {
             throw new Error("Calculation resulted in NaN.");
        }

        // Update the cell's displayed value and its internal data-value attribute
        cellElement.textContent = result;
        cellElement.setAttribute('data-value', result);
        updateLocalStorage(cellElement, content, result); // Store formula AND calculated value

    } catch (e) {
        console.error("Error calculating cell:", e);
        // If calculation fails, display the original formula and store it as text
        cellElement.textContent = content;
        cellElement.setAttribute('data-value', ''); 
        updateLocalStorage(cellElement, content, null);
    }
    return parseFloat(cellElement.textContent);
}

/**
 * Iterates over all cells containing formulas and recalculates them.
 */
function calculateAllFormulas() {
    const formulaCells = document.querySelectorAll('[contenteditable="true"]');
    formulaCells.forEach(cell => {
        let content = cell.textContent.trim();
        if (content.startsWith('=')) {
            calculateCell(cell);
        }
    });
}

/**
 * Updates the local storage for a given cell element.
 * @param {HTMLElement} cellElement - The cell element.
 * @param {string} content - The raw text content entered by the user (formula or value).
 * @param {number|null} [calculatedValue=null] - The calculated numeric value, if available.
 */
function updateLocalStorage(cellElement, content, calculatedValue = null) {
    const coords = getCoordinates(cellElement);
    if (!coords) return;

    let dataToStore = {
        content: content, // What the user typed (formula or text)
        value: calculatedValue !== null ? calculatedValue : parseFloat(content) || 0, // The actual numeric value
        color: cellElement.style.backgroundColor || '#ffffff'
    };

    // If we are storing a formula, ensure 'value' reflects the calculation result if possible
    if (typeof content === 'string' && content.startsWith('=')) {
         dataToStore.value = calculatedValue !== null ? calculatedValue : 0;
    } else {
        dataToStore.value = parseFloat(content) || 0;
    }

    const key = `spreadsheet_${coords}`;
    localStorage.setItem(key, JSON.stringify(dataToStore));
}


/**
 * Loads data from local storage and populates the spreadsheet.
 */
function loadDataFromLocalStorage() {
    const cells = document.querySelectorAll('[contenteditable="true"]');
    cells.forEach(cell => {
        const coords = getCoordinates(cell);
        const key = `spreadsheet_${coords}`;
        const storedData = localStorage.getItem(key);

        if (storedData) {
            try {
                const data = JSON.parse(storedData);
                // Restore content, value, and color
                cell.textContent = data.content;
                cell.setAttribute('data-value', data.value);
                cell.style.backgroundColor = data.color;

                // If the stored content is a formula, we must recalculate it immediately
                if (data.content && data.content.startsWith('=')) {
                    calculateCell(cell); // Recalculates and updates display/storage again
                } else {
                     updateLocalStorage(cell, data.content, data.value);
                }

            } catch (e) {
                console.error("Error loading data for", coords, ":", e);
            }
        }
    });
}


/**
 * Applies a background color to the selected cell.
 * @param {HTMLElement} cellElement - The cell element.
 * @param {string} color - The hex color code.
 */
function applyColor(cellElement, color) {
    cellElement.style.backgroundColor = color;
    // Update local storage with the new background color
    updateLocalStorage(cellElement, cellElement.textContent, parseFloat(cellElement.getAttribute('data-value') || 0));
}

/**
 * Event listener for applying colors via button click.
 */
document.getElementById('applyColorButton').addEventListener('click', function() {
    const color = document.getElementById('cellColorPicker').value;
    // Find the currently focused cell (or the first editable cell if none is focused)
    let activeCell = document.activeElement;

    if (!activeCell || !activeCell.hasAttribute('contenteditable')) {
        // Fallback: Select the first editable cell if nothing is focused
        const cells = document.querySelectorAll('[contenteditable="true"]');
        if (cells.length > 0) {
            activeCell = cells[0];
            activeCell.focus();
        } else {
            alert("Por favor, haz clic en una celda para aplicar el color.");
            return;
        }
    }

    applyColor(activeCell, color);
});


/**
 * Initializes the spreadsheet structure and sets up all necessary event listeners.
 */
function initializeSpreadsheet() {
    // 1. Setup Cell Editing and Event Listeners
    setupCellEditing();

    // 2. Initialize Data from Local Storage (if available)
    loadDataFromLocalStorage();

    // 3. Set up Row Deletion Listener
    const rowLabels = document.querySelectorAll('.row-label');
    rowLabels.forEach(label => {
        label.addEventListener('click', function() {
            // Confirm deletion to prevent accidental loss of data
            if (confirm("¿Está seguro de que desea eliminar esta fila? Esta acción no se puede deshacer.")) {
                // Find the parent row element (<tr>) and remove it entirely
                const row = this.closest('tr');
                if (row) {
                    row.remove();
                    // After removing a row, we should ideally update local storage 
                    // or recalculate dependent cells if necessary. For now, simple removal suffices.
                }
            }
        });
    });

    // Initial calculation run to populate formulas on load
    calculateAllFormulas();
}
