        // 1. Remove the row from the DOM
        rowElement.remove();

        // 2. Update local storage data structure (assuming we store all cell values)
        const rows = Array.from(document.querySelectorAll('#spreadsheet tbody tr'));
        let newSpreadsheetData = [];
        let rowIndexCounter = 1;

        rows.forEach(row => {
            if (row !== rowElement) {
                // Rebuild the data structure for persistence
                let rowData = {};
                const cells = row.querySelectorAll('td');
                cells.forEach((cell, index) => {
                    const cellId = cell.getAttribute('data-cell');
                    rowData[cellId] = cell.textContent.trim();
                });
                newSpreadsheetData.push(rowData);
            }
        });

        // Save the remaining data to local storage
        localStorage.setItem('spreadsheetData', JSON.stringify(newSpreadsheetData));
    }
}
