```javascript
function setupRowHidingListeners() {
    const rowLabels = document.querySelectorAll('.row-label');
    const hideButton = document.getElementById('hideRowButton');

    // Listener para seleccionar una fila al hacer clic en la etiqueta de la fila
    rowLabels.forEach(label => {
        label.addEventListener('click', function() {
            // Deseleccionar todas las etiquetas y filas primero
            document.querySelectorAll('.row-label').forEach(l => l.classList.remove('selected'));
            document.querySelectorAll('#spreadsheet tbody tr').forEach(r => r.classList.remove('selected-row'));

            // Seleccionar la etiqueta y la fila actualizadas
            this.classList.add('selected');
            const rowId = this.closest('tr').id;
            document.getElementById(rowId).classList.add('selected-row');
        });
    });

    // Listener para el botón de ocultar
    if (hideButton) {
        hideButton.addEventListener('click', function() {
            const selectedRow = document.querySelector('.selected-row');
            if (selectedRow) {
                // Ocultar la fila completa
                selectedRow.style.display = 'none';

                // Deseleccionar visualmente después de ocultarla
                selectedRow.classList.remove('selected-row'); 
                document.querySelector('.selected').classList.remove('selected');

            } else {
                alert("Por favor, selecciona una fila primero para ocultarla.");
            }
        });
    }
}
