function deleteColumn(columnLetter) {
    if (!columnLetter) return;

    const columnHeader = document.querySelector('#column-headers th:nth-child(' + (['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'].indexOf(columnLetter) + 2) + ')');
    if (!columnHeader) {
        console.error("No se encontró el encabezado de columna:", columnLetter);
        return;
    }

    // 1. Eliminar todas las celdas de la columna en el tbody
    const cellsToDelete = document.querySelectorAll(`#spreadsheet td[data-cell^="${columnLetter}"]`);
    cellsToDelete.forEach(cell => {
        cell.remove();
    });

    // 2. Eliminar el encabezado de la columna
    columnHeader.remove();

    // 3. Actualizar los datos en LocalStorage (simulación)
    // Nota: En una app real, se debería reindexar o manejar las claves de LS. Aquí solo simulamos la limpieza visual.
    alert(`Columna ${columnLetter} eliminada exitosamente.`);
    window.currentSelectedColumn = null;
    updateActionControls(null);
}
