function setBackgroundColorForColumn(columnLetter, color) {
    if (!columnLetter || !color) return;

    const cellsToColor = document.querySelectorAll(`#spreadsheet td[data-cell^="${columnLetter}"]`);
    cellsToColor.forEach(cell => {
        // Aplicar el fondo y asegurar que el texto sea visible
        cell.style.backgroundColor = color;
        // Si el fondo es oscuro, se podría necesitar cambiar el color del texto (foreground)
        if (isDarkColor(color)) {
            cell.style.color = '#ffffff'; // Texto blanco para contraste
        } else {
            cell.style.color = 'black'; // Texto negro por defecto
        }
    });

    alert(`Fondo de la columna ${columnLetter} cambiado a ${color}.`);
}

// Helper function to determine if a color is dark enough for white text contrast
function isDarkColor(hexColor) {
    const r = parseInt(hexColor.substring(1, 3), 16);
    const g = parseInt(hexColor.substring(3, 5), 16);
    const b = parseInt(hexColor.substring(5, 7), 16);
    // Simple check: if the sum of RGB components is low, it's dark.
    return (r * 299 + g * 587 + b * 114) < 200;
}
