/**
 * Configura la selección de columnas y el manejo del color de fondo.
 */
function setupColumnSelectionAndColoring() {
    const spreadsheet = document.getElementById('spreadsheet');
    const columnHeadersContainer = document.querySelector('.column-headers'); // Asumiendo que los encabezados están en esta clase/contenedor
    const applyColorButton = document.getElementById('applyColorButton');

    if (!columnHeadersContainer || !applyColorButton) {
        console.warn("Componentes de selección de columna o botón de color no encontrados.");
        return;
    }

    let selectedColumnLetter = null;

    // 1. Listener para seleccionar la columna haciendo clic en su letra (A, B, C...)
    columnHeadersContainer.addEventListener('click', function(event) {
        const target = event.target.closest('[data-col-letter]'); // Asumiendo que los encabezados tienen data-col-letter
        if (!target) return;

        // Limpiar selección anterior
        document.querySelectorAll('.column-header').forEach(el => el.classList.remove('selected'));

        const letter = target.getAttribute('data-col-letter');
        if (letter) {
            selectedColumnLetter = letter;
            target.classList.add('selected');
            console.log(`Columna seleccionada: ${letter}`);
        }
    });

    // 2. Listener para aplicar el color de fondo
    applyColorButton.addEventListener('click', function() {
        const colorPicker = document.getElementById('cellColorPicker');
        if (!colorPicker) return;

        const selectedColor = colorPicker.value;

        if (selectedColumnLetter && selectedColor) {
            // Obtener todas las celdas de la columna seleccionada
            const cellsInColumn = [];
            let rowCounter = 1;
            while (true) {
                const cellId = `${selectedColumnLetter}${rowCounter}`;
                const element = document.querySelector(`[data-cell="${cellId}"]`);
                if (!element) break; // Detener si no hay más celdas en esta columna

                cellsInColumn.push(element);
                rowCounter++;
            }

            // Aplicar el fondo a cada celda
            cellsInColumn.forEach(cell => {
                // Usamos style.backgroundColor para asegurar que se aplique directamente al TD, 
                // sobrescribiendo cualquier estilo CSS preexistente o de cálculo.
                cell.style.backgroundColor = selectedColor;
            });

            console.log(`Fondo ${selectedColor} aplicado a la columna ${selectedColumnLetter}.`);
        } else {
            alert("Por favor, selecciona una columna y elige un color.");
        }
    });
}
