    spreadsheet.addEventListener('blur', function(e) {
        const target = e.target;
        if (target && target.tagName === 'TD' && currentEditingCell === target) {
            saveCellValue(target);
            // Después de guardar, forzar el recálculo en la hoja completa
            calculateAllFormulas(); 
        }
    });

