    spreadsheet.addEventListener('keydown', function(e) {
        const target = e.target;
        if (target && target.tagName === 'TD' && currentEditingCell === target) {
            if (e.key === 'Enter') {
                e.preventDefault(); // Prevenir salto de línea en el DOM
                // Mover al siguiente elemento editable y perder foco para guardar
                const nextCell = target.parentNode.querySelector('td:next');
                if (nextCell) {
                    selectCellForEditing(nextCell);
                    nextCell.focus();
                    currentEditingCell = null; // Limpiar el estado de edición temporalmente
                } else {
                    // Si no hay siguiente, simplemente perder foco para guardar y salir
                    target.blur(); 
                }
            } else if (e.key === 'Tab' && !e.shiftKey) {
                 // Mover al siguiente elemento editable y perder foco para guardar
                const nextCell = target.parentNode.querySelector('td:next');
                if (nextCell) {
                    selectCellForEditing(nextCell);
                    nextCell.focus();
                    currentEditingCell = null; 
                } else {
                     target.blur();
                }
            }
        }
    });
}

/**
 * Selecciona una celda para edición, la enfoca y establece el estado de edición.
 * @param {HTMLElement} cellElement - El elemento TD a editar.
 */
function selectCellForEditing(cellElement) {
    // Deseleccionar cualquier otra celda primero
    document.querySelectorAll('#spreadsheet td').forEach(td => {
        td.classList.remove('selected');
        td.setAttribute('contenteditable', 'false');
    });

    // Seleccionar la nueva celda
    cellElement.classList.add('selected');
    cellElement.setAttribute('contenteditable', 'true');
    currentEditingCell = cellElement;
    cellElement.focus();
}


/**
 * Obtiene las coordenadas (fila, columna) de una celda dada su ID o elemento.
 * @param {string|HTMLElement} cellId - El ID de la celda ('A3') o el elemento TD.
 * @returns {{row: number, col: string}|null} Las coordenadas.
 */
function getCoordinates(cellId) {
    let target;
    if (typeof cellId === 'string') {
        // Si es una cadena como 'A3', necesitamos encontrar el elemento correspondiente
        const match = cellId.match(/([A-Z]+)(\d+)/i);
        if (!match) return null;
        const colLetter = match[1].toUpperCase();
        const rowNumber = parseInt(match[2]);

        // Buscar la celda por su atributo data-cell
        target = document.querySelector(`td[data-cell="${cellId}"]`);
    } else {
        target = cellId; // Ya es el elemento TD
    }

    if (!target) return null;

    const rowNumber = target.closest('tr').id.replace('row-', '');
    const colLetter = target.getAttribute('data-cell').match(/[A-Z]+/i)[0];

    return { row: parseInt(rowNumber), col: colLetter };
}


/**
 * Obtiene el ID de la celda a partir de coordenadas (fila, columna).
 * @param {number} row - Número de fila.
 * @param {string} col - Letra de columna ('A', 'B', etc.).
 * @returns {string} El ID de la celda ('A3').
 */
function getCellIdFromCoordinates(row, col) {
    return `${col}${row}`;
}

/**
 * Calcula el valor de una celda. Puede ser un número o una fórmula.
 * @param {HTMLElement} cellElement - El elemento TD a calcular.
 * @returns {string|number} El valor calculado (texto o número).
 */
function calculateCell(cellElement) {
    let value = cellElement.textContent.trim();

    if (!value) return '';

    // 1. Verificar si es una fórmula
    if (value.startsWith('=')) {
        try {
            // Evaluar la fórmula en el contexto de los valores actuales del DOM
            const formula = value.substring(1);
            let calculationContext = {};

            // Recolectar todos los valores numéricos visibles para que eval() pueda usarlos
            document.querySelectorAll('#spreadsheet td').forEach(td => {
                const coords = getCoordinates(td);
                if (coords) {
                    const key = `${coords.col}${coords.row}`;
                    let val = td.textContent.trim();
                    // Intentar convertir a número si es posible, sino mantener el string
                    calculationContext[key] = isNaN(parseFloat(val)) ? val : parseFloat(val);
                }
            });

            // Crear un entorno de ejecución seguro para evaluar la fórmula con los valores disponibles
            const result = eval(formula); 
            return typeof result === 'number' ? result.toFixed(2) : String(result);

        } catch (e) {
            console.error("Error al calcular la fórmula:", e);
            // Si falla el cálculo, mostrar el texto original o un error
            return "ERROR"; 
        }
    } else {
        // Es un valor simple
        return value;
    }
}

/**
 * Recalcula el contenido de una celda específica.
 * @param {HTMLElement} cellElement - El elemento TD a recalcular.
 */
function calculateCell(cellElement) {
    const calculatedValue = calculateCell(cellElement);
    // Actualizar el contenido visible y limpiar cualquier clase de error si existiera
    cellElement.textContent = calculatedValue; 
    cellElement.setAttribute('data-value', calculatedValue); // Mantener la data-value actualizada
}

/**
 * Recalcula todas las fórmulas en toda la hoja de cálculo.
 */
function calculateAllFormulas() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // Iterar sobre todas las filas (excluyendo el thead)
    const rows = spreadsheet.querySelectorAll('tbody tr');
    rows.forEach(row => {
        // Iterar sobre todas las celdas de datos en la fila
        const cells = row.querySelectorAll('td');
        cells.forEach(cell => {
            calculateCell(cell);
        });
    });
}

