 */
function loadDataFromLocalStorage() {
    const savedData = JSON.parse(localStorage.getItem('spreadsheetData')) || {};
    if (!savedData) return;

    for (const cellId in savedData) {
        const data = savedData[cellId];
        const cellElement = document.querySelector(`td[data-cell="${cellId}"]`);
        if (cellElement) {
            // Restaurar contenido y atributos de valor
            cellElement.textContent = data.value;
            cellElement.setAttribute('data-value', data.value);
            // Nota: El color se maneja por CSS/DOM, no lo restauramos aquí para evitar conflictos con el estado actual del usuario.
        }
    }

