### FUNCION: applyRowAction
```js
/**
 * R7 Helper: Aplica una acción (cambiar color o borrar contenido) a todas las celdas de una fila dada.
 * @param {string} rowId - El ID del contenedor de la fila (ej: 'row-3').
 * @param {('color'|'clear')} actionType - Tipo de acción a realizar.
 * @param {string | null} value - Valor asociado a la acción (ej: color hexadecimal o null).
 */
function applyRowAction(rowId, actionType, value) {
    const rowContainer = document.getElementById(rowId);
    if (!rowContainer) {
        console.error(`Contenedor de fila no encontrado con ID: ${rowId}`);
        return;
    }

    // Selecciona todos los elementos TD dentro del contenedor de la fila, excluyendo el label de la fila misma.
    // Usamos un selector más específico para evitar seleccionar celdas que no son datos.
    const cells = rowContainer.querySelectorAll('td:not(.row-label)'); 

    if (cells.length === 0) {
        console.warn(`No se encontraron celdas de datos en la fila ${rowId}.`);
        return;
    }

    if (actionType === 'color' && value !== null) {
        const color = value;
        cells.forEach(cell => {
            // Aplicar el fondo directamente al elemento TD
            cell.style.backgroundColor = color;
        });
    } else if (actionType === 'clear') {
        cells.forEach(cell => {
            // Borrar contenido y resetear estilo de fondo
            cell.innerText = '';
            cell.style.backgroundColor = ''; // Resetear el fondo
            cell.dataset.isCalculated = 'false';
        });
    } else {
        console.error("Acción o valor inválido proporcionado para la fila.");
    }
}
