function setupRowLabelListeners() {
    const rowLabels = document.querySelectorAll('.row-label');
    rowLabels.forEach(label => {
        label.addEventListener('click', function() {
            // Al hacer clic en el número de la fila, lo seleccionamos visualmente y guardamos su índice.
            document.querySelectorAll('.row-label').forEach(l => l.classList.remove('selected'));
            this.classList.add('selected');

            const rowIndex = parseInt(this.dataset.rowIndex);
            // Al seleccionar la fila, podemos enfocar el primer elemento para que el usuario pueda empezar a escribir/borrar.
            const firstCellId = getCellIdFromCoordinates(rowIndex, 0);
            const firstCell = document.querySelector(`[data-cell="${firstCellId}"]`);
            if (firstCell) {
                firstCell.focus();
            }
        });
    });
}
