### FUNCION: clearRowContent
```js
function clearRowContent(rowIndex) {
    console.log(`Limpiando contenido de la fila ${rowIndex + 1}...`);
    let clearedCount = 0;

    // Iterar sobre todos los elementos que tienen data-cell para encontrar aquellos en esta fila
    document.querySelectorAll('[data-cell]').forEach(element => {
        const cellId = element.getAttribute('data-cell');
        const coords = getCoordinates(cellId);

        if (coords.r === rowIndex) {
            // 1. Limpiar el contenido del DOM
            element.innerText = "";
            element.dataset.isCalculated = 'false'; // Resetear estado de cálculo

            // 2. Eliminar los datos de LocalStorage
            localStorage.removeItem(`spreadsheet_${cellId}`);
            clearedCount++;
        }
    });

    console.log(`${clearedCount} celdas limpiadas exitosamente.`);
    // Forzar un recálculo general o simplemente dejar que el usuario lo haga, ya que la limpieza rompe fórmulas.
}
```

### FUNCION: handleKeyDownForClear
```js
function handleKeyDownForClear(event) {
    const selectedLabel = document.querySelector('.row-label.selected');
    if (!selectedLabel) return;

    // Detectar si se presionó la tecla Supr (Delete key)
    if (event.key === 'Delete' || event.key === 'Backspace') {
        event.preventDefault(); // Prevenir el comportamiento por defecto del navegador
        const rowIndex = parseInt(selectedLabel.dataset.rowIndex);
        clearRowContent(rowIndex);
    }
}
