function clearRowContent(rowIndex) {
    // Selecciona todas las celdas editables (data-cell) que pertenecen a la fila dada.
    const rowCells = document.querySelectorAll(`[data-row="${rowIndex}"] [data-cell]`);
    if (rowCells.length === 0) {
