function setupHeaderListeners() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) return;

    // Usamos event delegation en el contenedor principal para capturar eventos 
    // sobre las celdas de encabezado (th), que representan columnas.
    spreadsheet.addEventListener('contextmenu', function(event) {
        const target = event.target;

        // Verificamos si el objetivo es un encabezado de columna (th) y no es la cabecera general.
        if (target.tagName === 'TH' && !target.parentElement.classList.contains('header-row')) {
            event.preventDefault(); // Prevenir el menú contextual por defecto

            // Intentar obtener el índice basado en la posición de los elementos hermanos
            let columnIndex = Array.from(target.parentNode.children).indexOf(target);

            if (columnIndex === -1) return; 

            const columnName = String.fromCharCode('A'.charCodeAt(0) + columnIndex);

            // Mostrar menú contextual personalizado
            showContextMenu(event, 'column', columnName, columnIndex);
        }
    });
}

/**
 * Configura los listeners para la manipulación de filas (ocultar/mostrar).
 */
function setupRowLabelListeners() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) return;

    // Usamos event delegation en el contenedor principal para capturar eventos 
    // sobre las etiquetas de fila (row labels, que asumimos están en la primera columna).
    spreadsheet.addEventListener('contextmenu', function(event) {
        const target = event.target;

        // Verificamos si el objetivo es una etiqueta de fila (asumiendo que tienen clase 'row-label')
        if (target.classList.contains('row-label')) {
            event.preventDefault(); // Prevenir el menú contextual por defecto

            // El índice de la fila se puede obtener del texto o un atributo data-row
            const rowNumber = parseInt(target.innerText);
            const rowIndex = rowNumber - 1;

            if (isNaN(rowIndex)) return;

            // Mostrar menú contextual personalizado
            showContextMenu(event, 'row', String(rowNumber), rowIndex);
        }
    });
}


/**
 * Muestra un menú contextual simulado para ocultar/mostrar filas o columnas.
 * @param {Event} event - El evento de contexto del ratón.
 * @param {'column'|'row'} type - Tipo de elemento (columna o fila).
 * @param {string} identifier - Identificador visible (ej: 'A', '5').
 * @param {number} index - Índice base 0 del elemento.
 */
function showContextMenu(event, type, identifier, index) {
    // Limpiar cualquier menú existente
    let menu = document.getElementById('context-menu');
    if (menu) menu.remove();

    const menuHTML = `
        <div id="context-menu" class="context-menu">
            <div class="menu-item" data-action="${type}-hide">Ocultar ${identifier}</div>
            <div class="menu-item" data-action="${type}-show">Mostrar ${identifier}</div>
        </div>
    `;

    const menuElement = document.createElement('div');
    menuElement.innerHTML = menuHTML;
    document.body.appendChild(menuElement.firstChild);

    // Posicionar el menú en la posición del clic
    const menu = document.getElementById('context-menu');
    if (menu) {
        menu.style.left = `${event.clientX}px`;
        menu.style.top = `${event.clientY}px`;
    }

    // Añadir listener para manejar la acción del menú
    document.querySelectorAll('.context-menu .menu-item').forEach(item => {
        item.addEventListener('click', function() {
            const action = this.getAttribute('data-action');
            if (action === 'column-hide') {
                hideColumn(index);
            } else if (action === 'column-show') {
                showColumn(index);
            } else if (action === 'row-hide') {
                hideRow(index);
            } else if (action === 'row-show') {
                showRow(index);
            }

            // Ocultar el menú después de la acción
            if (menu) menu.remove();
        });
    });
}


