function handleHideRow(rowIndex) {
    // 1. Select the row label element using the index
    const rowLabel = document.querySelector('.row-label[data-row-index="' + rowIndex + '"]');
    if (!rowLabel) return;

    // 2. Get the parent row (<tr>) containing all cells and the label
    const rowElement = rowLabel.closest('tr');
    if (!rowElement) return;

    // 3. Iterate over all children (label + data cells) to clear content and hide them
    Array.from(rowElement.children).forEach(child => {
        // Clear content regardless of element type
        child.textContent = '';
        // Hide the cell/label
        child.style.display = 'none';
    });

    // 4. Finally, ensure the entire row is hidden (though individual children hiding should suffice)
    rowElement.style.display = 'none';
}
