function handleHideColumn(colIndex) {
    // 1. Hide the header cell itself
    const colHeader = document.querySelector(`.col-header[data-col-index="${colIndex}"]`);
    if (colHeader) {
        colHeader.style.display = 'none';
    }

    // 2. Find all data cells in this column across all rows (tbody td:nth-child(N))
    const columnIndex = colIndex + 1; // CSS nth-child is 1-based, and we skip the row label th
    const cellsToHide = document.querySelectorAll('#spreadsheet tbody tr td:nth-child(' + columnIndex + ')');

    cellsToHide.forEach(cell => {
        // Clear content
        cell.textContent = '';
        // Hide the cell
        cell.style.display = 'none';
    });
}
