function setupRowContextMenu() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // Listener para clic derecho en la columna de etiquetas de fila (la primera TD).
    spreadsheet.addEventListener('contextmenu', function(e) {
        // Verificar si el objetivo es una celda etiqueta de fila
        const target = e.target.closest('.row-label');
        if (!target) return;

        e.preventDefault(); // Prevenir el menú contextual por defecto del navegador

        const rowElement = target.closest('tr');
        if (!rowElement) return;

        // 1. Crear o recuperar el menú contextual
        let menu = document.getElementById('contextMenu');
        if (!menu) {
            menu = document.createElement('div');
            menu.id = 'contextMenu';
            menu.style.position = 'absolute';
            menu.style.backgroundColor = '#fff';
            menu.style.border = '1px solid #ccc';
            menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
            menu.style.zIndex = '1000';
            menu.style.padding = '5px';
            menu.style.display = 'none';
            document.body.appendChild(menu);
        }

        // Limpiar opciones anteriores
        menu.innerHTML = ''; 

        // Añadir opción Borrar Fila
        const deleteItem = document.createElement('div');
        deleteItem.textContent = '🗑️ Borrar Fila';
        deleteItem.style.cursor = 'pointer';
        deleteItem.style.padding = '5px';
        deleteItem.style.fontSize = '14px';
        deleteItem.onmouseover = () => deleteItem.style.backgroundColor = '#f0f0ff';
        deleteItem.onmouseout = () => deleteItem.style.backgroundColor = 'transparent';

        // Adjuntar el manejador de eliminación
        deleteItem.onclick = (e) => {
            e.stopPropagation(); 
            if (confirm('¿Está seguro de que desea borrar esta fila? Esta acción no se puede deshacer.')) {
                deleteRow(rowElement);
            }
            menu.style.display = 'none';
        };

        // Añadir el nuevo elemento al menú
        menu.appendChild(deleteItem);

        // 2. Posicionar el menú cerca del cursor
        menu.style.left = `${e.clientX + 10}px`;
        menu.style.top = `${e.clientY + 10}px`;
        menu.style.display = 'block';
    });
}
