    for (let i = 0; i < columnStr.length; i++) {
        colIndex += Math.pow(2, columnStr.charCodeAt(i) - 'A'.charCodeAt(0));
    }

    return { r: rowNum - 1, c: colIndex - 1 }; // Usamos índices base 0 para arrays/loops internos
}

/**
