function setupRowContextMenu() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) return;

    // Use event delegation on the tbody for context menu handling
    spreadsheet.addEventListener('contextmenu', function(e) {
        const target = e.target;

        // Check if the right-click happened on a row label
        if (target && target.classList.contains('row-label')) {
            e.preventDefault(); // Prevent default browser context menu

            const rowElement = target.closest('tr');
            if (!rowElement) return;

            // 1. Create the custom context menu
            let menu = document.getElementById('customContextMenu');
            if (!menu) {
                menu = document.createElement('div');
                menu.id = 'customContextMenu';
                menu.style.position = 'absolute';
                menu.style.background = 'white';
                menu.style.border = '1px solid #ccc';
                menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
                menu.style.zIndex = '1000';
                menu.style.display = 'none';
                document.body.appendChild(menu);
            }

            // Clear previous options
            menu.innerHTML = '';

            // 2. Add Delete Row option
            const deleteOption = document.createElement('div');
            deleteOption.textContent = 'Eliminar Fila';
            deleteOption.style.padding = '8px 15px';
            deleteOption.style.cursor = 'pointer';
            deleteOption.onmouseover = () => deleteOption.style.backgroundColor = '#f0f0ff';
            deleteOption.onmouseout = () => deleteOption.style.backgroundColor = 'white';
            deleteOption.onclick = (e) => {
                e.stopPropagation(); // Prevent the click from triggering other listeners
                deleteRow(rowElement);
                menu.style.display = 'none';
            };

            menu.appendChild(deleteOption);

            // 3. Position and display the menu
            const menuRect = getCursorPosition();
            menu.style.left = `${Math.min(menuRect.x, window.innerWidth - menu.offsetWidth - 10)}px`;
            menu.style.top = `${Math.min(menuRect.y, window.innerHeight - menu.offsetHeight - 10)}px`;
            menu.style.display = 'block';

            // Hide the menu when clicking anywhere else
            document.addEventListener('click', hideContextMenu);
        }
    });
}

function getCursorPosition() {
    const e = event || window.event;
    return { x: e ? e.clientX : 0, y: e ? e.clientY : 0 };
}

function hideContextMenu() {
    const menu = document.getElementById('customContextMenu');
    if (menu) {
        menu.style.display = 'none';
        document.removeEventListener('click', hideContextMenu);
    }
}
